module sync_fifo #(
  parameter DEPTH   = 8,  // Must be power-of-two for ring-pointer indexing
  parameter DATA_W  = 8
)(
  input  wire              clk,
  input  wire              reset,

  input  wire              push_i,
  input  wire [DATA_W-1:0] push_data_i,

  input  wire              pop_i,
  output wire [DATA_W-1:0] pop_data_o,

  output wire              full_o,
  output wire              empty_o
);

  localparam PTR_W = $clog2(DEPTH);

  logic [PTR_W:0] rd_ptr_q, nxt_rd_ptr;
  logic [PTR_W:0] wr_ptr_q, nxt_wr_ptr;

  // Memory array of size DEPTH=8
  logic [DATA_W-1:0] fifo_mem [0:DEPTH-1];
  logic [DATA_W-1:0] fifo_pop_data;

  assign pop_data_o = fifo_pop_data;

  // Pointer flops
  always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
      rd_ptr_q <= '0;
      wr_ptr_q <= '0;
    end else begin
      rd_ptr_q <= nxt_rd_ptr;
      wr_ptr_q <= nxt_wr_ptr;
    end
  end

  // Next-state logic for pointers
  always_comb begin
    // Default no movement
    nxt_rd_ptr    = rd_ptr_q;
    nxt_wr_ptr    = wr_ptr_q;
    fifo_pop_data = fifo_mem[rd_ptr_q[PTR_W-1:0]];

    case ({pop_i, push_i})
      2'b01: // PUSH
        nxt_wr_ptr = wr_ptr_q + 1;
      2'b10: // POP
        nxt_rd_ptr = rd_ptr_q + 1;
      2'b11: // PUSH + POP
        begin
          nxt_wr_ptr = wr_ptr_q + 1;
          nxt_rd_ptr = rd_ptr_q + 1;
        end
      default: /* 2'b00 */ ;
    endcase
  end

  // Write memory
  always_ff @(posedge clk) begin
    if (push_i) begin
      fifo_mem[wr_ptr_q[PTR_W-1:0]] <= push_data_i;
    end
  end

  // Empty/Full checks
  assign empty_o = (wr_ptr_q == rd_ptr_q);
  assign full_o  = (wr_ptr_q[PTR_W]  != rd_ptr_q[PTR_W]) &&
                   (wr_ptr_q[PTR_W-1:0] == rd_ptr_q[PTR_W-1:0]);

endmodule

context.verif/tb_low_power_channel.sv:
`timescale 1ns / 1ps

module tb_low_power_channel;

  // -------------------------------------------------------------------
  // DUT Interface Signals
  // -------------------------------------------------------------------
  logic         clk;
  logic         reset;

  // DUT inputs
  logic         if_wakeup_i;
  logic         wr_valid_i;
  logic [7:0]   wr_payload_i;
  logic         wr_done_i;
  logic         rd_valid_i;
  logic         qreqn_i;

  // DUT outputs
  wire          wr_flush_o;
  wire [7:0]    rd_payload_o;
  wire          qacceptn_o;
  wire          qactive_o;

  // -------------------------------------------------------------------
  // DUT Instantiation
  // -------------------------------------------------------------------
  low_power_channel dut (
    .clk          (clk),
    .reset        (reset),
    .if_wakeup_i  (if_wakeup_i),
    .wr_valid_i   (wr_valid_i),
    .wr_payload_i (wr_payload_i),
    .wr_flush_o   (wr_flush_o),
    .wr_done_i    (wr_done_i),
    .rd_valid_i   (rd_valid_i),
    .rd_payload_o (rd_payload_o),
    .qreqn_i      (qreqn_i),
    .qacceptn_o   (qacceptn_o),
    .qactive_o    (qactive_o)
  );

  // -------------------------------------------------------------------
  // Clock Generation
  // -------------------------------------------------------------------
  always #5 clk = ~clk;

  // -------------------------------------------------------------------
  // Scoreboard / Tracking
  // -------------------------------------------------------------------
  // We will store written data in a queue and compare with read data
  // to ensure correctness.
  typedef bit [7:0] data_t;
  data_t write_queue[$];
  data_t read_data;

  // Track errors
  integer error_count = 0;

  // Simple mechanism to log errors
  task report_error(string msg);
    begin
      error_count++;
      $display("[ERROR] %s at time %0t", msg, $time);
    end
  endtask

  // -------------------------------------------------------------------
  // Initialization & Reset
  // -------------------------------------------------------------------
  initial begin
    clk          = 0;
    reset        = 0;
    if_wakeup_i  = 0;
    wr_valid_i   = 0;
    wr_payload_i = 0;
    wr_done_i    = 0;
    rd_valid_i   = 0;
    qreqn_i      = 1; // Start in ST_Q_RUN

    // Apply reset
    apply_reset;
    // Run test scenarios
    scenario1_reset_behavior;
    scenario2_write_read;
    scenario3_fifo_overflow_attempt;
    scenario4_fifo_underflow_attempt;
    scenario5_qreq_flush_handshake;
    scenario6_wakeup_signal_test;

    // Optional random/stress test
    scenario7_random_stress;

    // Final summary
    if (error_count == 0) begin
      $display("\nAll tests PASSED!");
    end else begin
      $display("\nTest FAILED with %0d errors!", error_count);
    end

    $finish;
  end

  // -------------------------------------------------------------------
  // Reset Task
  // -------------------------------------------------------------------
  task apply_reset;
    begin
      reset = 1;
      repeat (2) @(posedge clk); // hold reset for a couple of cycles
      reset = 0;
      repeat (2) @(posedge clk);
    end
  endtask

  // -------------------------------------------------------------------
  // Scenario #1: Reset Behavior
  //   Pass/Fail Criteria:
  //   - After reset, qacceptn_o == 1, qactive_o == 0, wr_flush_o == 0
  // -------------------------------------------------------------------
  task scenario1_reset_behavior;
    begin
      $display("\n--- SCENARIO 1: Reset Behavior ---");
      // Right after apply_reset, check signals
      @(negedge clk);
      if (qacceptn_o !== 1'b1)
        report_error("qacceptn_o should be 1 after reset");
      if (qactive_o !== 1'b0)
        report_error("qactive_o should be 0 after reset");
      if (wr_flush_o !== 1'b0)
        report_error("wr_flush_o should be 0 after reset");

      $display("Scenario 1 completed.");
    end
  endtask

  // -------------------------------------------------------------------
  // Scenario #2: Simple Write/Read
  //   Pass/Fail Criteria:
  //   - Data read = Data written (in order).
  //   - No unexpected assertions of wr_flush_o.
  // -------------------------------------------------------------------
  task scenario2_write_read;
    begin
      $display("\n--- SCENARIO 2: Simple Write/Read ---");
      // Write a few data items
      write_data(8'hAA);
      write_data(8'hBB);
      write_data(8'hCC);

      // Now read them back
      read_data_item; // expects 8'hAA
      read_data_item; // expects 8'hBB
      read_data_item; // expects 8'hCC

      // Check no extra flush was triggered
      if (wr_flush_o !== 1'b0)
        report_error("wr_flush_o should not have asserted in normal write/read scenario");

      $display("Scenario 2 completed.");
    end
  endtask

  // Write a data item into the DUT
  task write_data(input [7:0] data_in);
    begin
      @(posedge clk);
      wr_valid_i   = 1'b1;
      wr_payload_i = data_in;
      write_queue.push_back(data_in);
      @(posedge clk);
      wr_valid_i   = 1'b0;
      wr_payload_i = 8'h00; // idle
      @(posedge clk);
    end
  endtask

  // Read a data item from the DUT and check scoreboard
  task read_data_item;
    begin
      // Only attempt read if scoreboard says we have data
      if (write_queue.size() == 0) begin
        report_error("Read requested but scoreboard is empty");
        return;
      end

      // Drive read
      @(posedge clk);
      rd_valid_i = 1'b1;
      @(posedge clk);
      rd_valid_i = 1'b0;

      // The read data will appear combinationally at rd_payload_o
      // We'll sample at the next clock for stable checking
      read_data = rd_payload_o;
      // Compare with scoreboard front
      if (read_data !== write_queue[0]) begin
        report_error($sformatf("Read data mismatch. Expected %h, got %h",
                               write_queue[0], read_data));
      end
      // Pop from scoreboard
      write_queue.pop_front();
      @(posedge clk);
    end
  endtask

  // -------------------------------------------------------------------
  // Scenario #3: FIFO Overflow Attempt
  //   Pass/Fail Criteria:
  //   - Confirm design’s defined behavior. Possibly losing data or ignoring push
  //     if the FIFO is full. Make sure no unexpected lock-ups.
  // -------------------------------------------------------------------
  task scenario3_fifo_overflow_attempt;
    integer i;
    begin
      $display("\n--- SCENARIO 3: FIFO Overflow Attempt ---");
      // FIFO has DEPTH=6 in the DUT. Let's write more than 6 without reads.
      for (i = 0; i < 8; i++) begin
        write_data(i[7:0]);
      end

      // Now read all we can. The scoreboard expects 8 items, but the
      // actual FIFO can only hold 6. If the design does not gate wr_valid,
      // you might see data lost or overwritten.
      // We read 8 times to see what comes out.
      for (i = 0; i < 8; i++) begin
        read_data_item;
      end

      // If the design is not gating writes, you may see mismatch errors.
      // We only confirm it doesn't wedge or produce X states unexpectedly.
      $display("Scenario 3 completed. Check for mismatch errors or stable behavior.");
    end
  endtask

  // -------------------------------------------------------------------
  // Scenario #4: FIFO Underflow Attempt
  //   Pass/Fail Criteria:
  //   - Attempt reading from empty FIFO. Check that no corruption or
  //     unexpected transitions occur.
  // -------------------------------------------------------------------
  task scenario4_fifo_underflow_attempt;
    integer i;
    begin
      $display("\n--- SCENARIO 4: FIFO Underflow Attempt ---");
      // Ensure FIFO is empty: no writes
      // Attempt multiple reads
      for (i = 0; i < 3; i++) begin
        @(posedge clk);
        rd_valid_i = 1'b1;
        @(posedge clk);
        rd_valid_i = 1'b0;
        // Check read data (may remain at a previous or undefined value)
        $display("Read data = %h (expected empty FIFO)", rd_payload_o);
      end

      // As long as the design does not hang or produce spurious flush,
      // we consider this scenario pass if no errors have been reported.
      $display("Scenario 4 completed.");
    end
  endtask

  // -------------------------------------------------------------------
  // Scenario #5: QREQ Handshake and Flush
  //   Pass/Fail Criteria:
  //   - wr_flush_o must assert when qreqn_i goes low (ST_Q_REQUEST)
  //     and remain asserted until wr_done_i is high and FIFO empties.
  //   - qacceptn_o must go low once flush completes in ST_Q_STOPPED.
  // -------------------------------------------------------------------
  task scenario5_qreq_flush_handshake;
    begin
      $display("\n--- SCENARIO 5: QREQ Handshake and Flush ---");
      // 1) Put some data in FIFO, do not read them
      write_data(8'hA0);
      write_data(8'hB1);

      // 2) Deassert wr_done_i, so the flush cannot complete
      wr_done_i = 0;

      // 3) Pull qreqn_i low => request Q-channel
      @(posedge clk);
      qreqn_i = 0;

      // Expect the state machine to move from ST_Q_RUN -> ST_Q_REQUEST
      // Check if wr_flush_o = 1
      // We'll wait a few cycles and check
      repeat (2) @(posedge clk);
      if (wr_flush_o !== 1'b1) begin
        report_error("wr_flush_o should be asserted in ST_Q_REQUEST");
      end

      // 4) Now let the upstream complete: wr_done_i=1 => flush completes
      //    Wait for FIFO to empty as well. Let's do a quick read:
      read_data_item; // read 8'hA0
      read_data_item; // read 8'hB1

      // The FIFO is now empty but we also must keep wr_done_i = 1
      @(posedge clk);
      wr_done_i = 1'b1;

      // Wait a bit to let state machine transition
      repeat (2) @(posedge clk);

      // Now, we expect wr_flush_o = 0 (since flush completed) and
      // qacceptn_o to drive low (since ST_Q_STOPPED).
      if (wr_flush_o !== 1'b0)
        report_error("wr_flush_o should be deasserted after flush completes");

      // Because we are in ST_Q_STOPPED, qacceptn_o should be 1'b0
      // (the design sets qacceptn_o = ~qaccept, so if we accept=1 => qacceptn=0)
      if (qacceptn_o !== 1'b0)
        report_error("qacceptn_o should be 0 in ST_Q_STOPPED");

      // 5) Re-assert qreqn_i => ST_Q_EXIT => eventually qacceptn_o = 1,
      @(posedge clk);
      qreqn_i = 1'b1;
      repeat (2) @(posedge clk);
      repeat(2) @(posedge clk);  // <---- ADD at least 2 cycles of wait
      if (qacceptn_o !== 1'b1)
        report_error("qacceptn_o should go back to 1 in ST_Q_RUN eventually");

      // Return signals to idle
      wr_done_i = 0;
      $display("Scenario 5 completed.");
    end
  endtask

  // -------------------------------------------------------------------
  // Scenario #6: Wakeup Signal Check
  //   Pass/Fail Criteria:
  //   - If if_wakeup_i=1 with an empty FIFO, qactive_o should still assert.
  //   - When if_wakeup_i=0, qactive_o should deassert if no FIFO activity.
  // -------------------------------------------------------------------
  task scenario6_wakeup_signal_test;
    begin
      $display("\n--- SCENARIO 6: Wakeup Signal Check ---");
      // Ensure FIFO is empty from previous scenario
      // No writes or reads
      if_wakeup_i = 1'b1;
      @(posedge clk);
      if (qactive_o !== 1'b1)
        report_error("qactive_o should be high due to wakeup");

      // Now deassert wakeup
      if_wakeup_i = 1'b0;
      repeat (2) @(posedge clk);
      if (qactive_o !== 1'b0)
        report_error("qactive_o should return low when wakeup is cleared and FIFO idle");

      $display("Scenario 6 completed.");
    end
  endtask

  // -------------------------------------------------------------------
  // Scenario #7: Optional Random/Stress (example skeleton)
  //   Pass/Fail Criteria:
  //   - No data mismatches or illegal state machine transitions.
  //   - Potential to uncover corner cases more systematically.
  // -------------------------------------------------------------------

  task scenario7_random_stress;
    integer i;
    begin
      $display("\n--- SCENARIO 7: Random/Stress Test ---");
      for (i = 0; i < 100; i++) begin
        // Random writes
        wr_valid_i   = $urandom_range(0,1);
        wr_payload_i = $urandom_range(0,255);
        if (wr_valid_i) write_queue.push_back(wr_payload_i);

        // Random reads
        rd_valid_i   = $urandom_range(0,1);
        if (rd_valid_i && write_queue.size() > 0) begin
          // scoreboard check after the cycle
        end

        // Random QREQ toggles
        if ($urandom_range(0,50) == 0) qreqn_i = ~qreqn_i;

        // Random wakeup
        if_wakeup_i = $urandom_range(0,1);

        // Random wr_done_i
        wr_done_i  = $urandom_range(0,1);

        @(posedge clk);
      end

      // Turn off writes, reads, wait some cycles
      wr_valid_i   = 0;
      rd_valid_i   = 0;
      if_wakeup_i  = 0;
      wr_done_i    = 1;
      repeat (10) @(posedge clk);

      $display("Scenario 7 completed (Random/Stress).");
    end
  endtask


endmodule

context.verif/multiplexer_tb.sv:
`timescale 1ns/1ps

module tb_multiplexer;

  reg clk;
  reg rst_n;
  reg [8*3-1:0] inp;
  reg [1:0] sel;
  reg bypass;
  wire [7:0] out;
  integer i, j;
  reg [7:0] expected;

  multiplexer #(
      .DATA_WIDTH(8),
      .NUM_INPUTS(3),
      .REGISTER_OUTPUT(1),
      .HAS_DEFAULT(1),
      .DEFAULT_VALUE(8'h55)
  ) dut (
      .clk(clk),
      .rst_n(rst_n),
      .inp(inp),
      .sel(sel),
      .bypass(bypass),
      .out(out)
  );

  always #5 clk = ~clk;

  initial begin
    clk = 0; rst_n = 0; inp = 0; sel = 0; bypass = 0;
    repeat(2) @(posedge clk);
    rst_n = 1;
    repeat(2) @(posedge clk);
    for (i = 0; i < 10; i = i + 1) begin
      inp = {($random() & 8'hFF), ($random() & 8'hFF), ($random() & 8'hFF)};
      for (j = 0; j < 4; j = j + 1) begin
        sel = j[1:0];
        bypass = 0;
        #1;
        if (sel < 3) expected = inp[sel*8 +: 8];
        else         expected = 8'h55;
        @(posedge clk);
        @(posedge clk);
        if (out !== expected)
          $display("Time=%0t Sel=%0d Bypass=%0b Inp=%0h Expected=%0h Got=%0h", $time, sel, bypass, inp, expected, out);
        else
          $display("Time=%0t PASSED Sel=%0d Bypass=%0b", $time, sel, bypass);

        bypass = 1;
        #1;
        expected = inp[0 +: 8];
        @(posedge clk);
        @(posedge clk);
        if (out !== expected)
          $display("Time=%0t Sel=%0d Bypass=%0b Inp=%0h Expected=%0h Got=%0h", $time, sel, bypass, inp, expected, out);
        else
          $display("Time=%0t PASSED Sel=%0d Bypass=%0b", $time, sel, bypass);
      end
    end
    $finish;
  end

endmodule

context.verif/signed_comparator_tb.sv:
`timescale 1ns/1ps

module tb_signed_comparator;

reg clk;
reg rst_n;
reg enable;
reg bypass;
reg signed [15:0] a;
reg signed [15:0] b;
wire gt, lt, eq;

localparam DATA_WIDTH       = 16;
localparam REGISTER_OUTPUT  = 1;
localparam ENABLE_TOLERANCE = 1;
localparam TOLERANCE        = 2;
localparam SHIFT_LEFT       = 1;

signed_comparator #(
  .DATA_WIDTH(DATA_WIDTH),
  .REGISTER_OUTPUT(REGISTER_OUTPUT),
  .ENABLE_TOLERANCE(ENABLE_TOLERANCE),
  .TOLERANCE(TOLERANCE),
  .SHIFT_LEFT(SHIFT_LEFT)
) dut (
  .clk(clk),
  .rst_n(rst_n),
  .enable(enable),
  .bypass(bypass),
  .a(a),
  .b(b),
  .gt(gt),
  .lt(lt),
  .eq(eq)
);

always #5 clk = ~clk;

initial begin
  clk = 0;
  rst_n = 0;
  enable = 0;
  bypass = 0;
  a = 0;
  b = 0;
  repeat(2) @(posedge clk);
  rst_n = 1;
  repeat(2) @(posedge clk);

  test_case( 100,  100, 0, 1);
  test_case(  10,  -10, 0, 1);
  test_case(  -5,    5, 0, 1);
  test_case(  50,   52, 0, 1);  // near difference -> tolerance
  test_case(  51,   52, 0, 1);  // difference 1 -> eq due to TOLERANCE=2
  test_case(  53,   50, 0, 1);  // difference 3 -> not within tolerance
  test_case( 123, -123, 1, 1);  // bypass => eq=1
  test_case( 500, -500, 0, 0);  // enable=0 => eq=0,gt=0,lt=0
  repeat(2) @(posedge clk);

  integer i;
  for (i = 0; i < 5; i = i + 1) begin
    test_case($random, $random, $random%2, $random%2);
  end

  $finish;
end

task test_case;
  input signed [15:0] a_val;
  input signed [15:0] b_val;
  input bypass_val;
  input enable_val;
begin
  a = a_val;
  b = b_val;
  bypass = bypass_val;
  enable = enable_val;
  @(posedge clk);
  @(posedge clk);

  check_output(a_val, b_val, bypass_val, enable_val);
end
endtask

task check_output;
  input signed [15:0] a_val;
  input signed [15:0] b_val;
  input bypass_val;
  input enable_val;
  reg signed [DATA_WIDTH-1:0] a_shift, b_shift;
  reg signed [DATA_WIDTH:0] diff_abs;
  reg exp_gt, exp_lt, exp_eq;
begin
  a_shift = a_val <<< SHIFT_LEFT;
  b_shift = b_val <<< SHIFT_LEFT;
  diff_abs = (a_shift - b_shift);
  if (diff_abs < 0) diff_abs = -diff_abs;

  if (bypass_val) begin
    exp_gt = 0; exp_lt = 0; exp_eq = 1;
  end else if (!enable_val) begin
    exp_gt = 0; exp_lt = 0; exp_eq = 0;
  end else begin
    if (ENABLE_TOLERANCE && (diff_abs <= TOLERANCE)) begin
      exp_gt = 0; exp_lt = 0; exp_eq = 1;
    end else if (a_shift > b_shift) begin
      exp_gt = 1; exp_lt = 0; exp_eq = 0;
    end else if (a_shift < b_shift) begin
      exp_gt = 0; exp_lt = 1; exp_eq = 0;
    end else begin
      exp_gt = 0; exp_lt = 0; exp_eq = 1;
    end
  end

  if (gt !== exp_gt || lt !== exp_lt || eq !== exp_eq) begin
    $display("Time=%0t FAIL: a=%d b=%d bypass=%b en=%b SHIFT_LEFT=%0d TOL=%0d => gt=%b lt=%b eq=%b (exp: %b %b %b)",
      $time, a_val, b_val, bypass_val, enable_val, SHIFT_LEFT, TOLERANCE,
      gt, lt, eq, exp_gt, exp_lt, exp_eq);
  end else begin
    $display("Time=%0t PASS: a=%d b=%d bypass=%b en=%b SHIFT_LEFT=%0d TOL=%0d => gt=%b lt=%b eq=%b",
      $time, a_val, b_val, bypass_val, enable_val, SHIFT_LEFT, TOLERANCE, gt, lt, eq);
  end
end
endtask

endmodule

context.verif/swizzler_tb.sv:
`timescale 1ns / 1ps

module tb_swizzler;

parameter NUM_LANES = 4;
parameter DATA_WIDTH = 8;
parameter REGISTER_OUTPUT = 0;
parameter ENABLE_PARITY_CHECK = 1;

reg clk;
reg rst_n;
reg bypass;
reg [NUM_LANES*DATA_WIDTH-1:0] data_in;
reg [NUM_LANES*$clog2(NUM_LANES)-1:0] swizzle_map_flat;
wire [NUM_LANES*DATA_WIDTH-1:0] data_out;
wire parity_error;

swizzler #(
    .NUM_LANES(NUM_LANES),
    .DATA_WIDTH(DATA_WIDTH),
    .REGISTER_OUTPUT(REGISTER_OUTPUT),
    .ENABLE_PARITY_CHECK(ENABLE_PARITY_CHECK)
) dut (
    .clk(clk),
    .rst_n(rst_n),
    .bypass(bypass),
    .data_in(data_in),
    .swizzle_map_flat(swizzle_map_flat),
    .data_out(data_out),
    .parity_error(parity_error)
);

logic [DATA_WIDTH-1:0] input_lanes [NUM_LANES-1:0];
logic [DATA_WIDTH-1:0] expected_lanes [NUM_LANES-1:0];
logic [DATA_WIDTH-1:0] output_lanes [NUM_LANES-1:0];
logic [$clog2(NUM_LANES)-1:0] swizzle_map [NUM_LANES-1:0];

integer i;

initial begin
    clk = 0;
    forever #5 clk = ~clk;
end

initial begin
    rst_n = 0;
    bypass = 0;
    data_in = 0;
    swizzle_map_flat = 0;
    #15;
    rst_n = 1;

    test_bypass();
    test_identity();
    test_reverse();
    test_custom();

    $display("All tests completed.");
    $finish;
end

task test_bypass;
    $display("Test Case: Bypass Mode");
    bypass = 1;
    for (i = 0; i < NUM_LANES; i++) begin
        input_lanes[i] = i + 1;
    end
    flatten_input();
    @(posedge clk);
    @(posedge clk);
    unpack_output();
    for (i = 0; i < NUM_LANES; i++) begin
        expected_lanes[i] = input_lanes[i];
    end
    check_output("Bypass");
endtask

task test_identity;
    $display("Test Case: Identity Mapping");
    bypass = 0;
    for (i = 0; i < NUM_LANES; i++) begin
        swizzle_map[i] = i;
        input_lanes[i] = i + 10;
    end
    flatten_swizzle_map();
    flatten_input();
    @(posedge clk);
    @(posedge clk);
    unpack_output();
    for (i = 0; i < NUM_LANES; i++) begin
        expected_lanes[i] = input_lanes[i];
    end
    check_output("Identity");
endtask

task test_reverse;
    $display("Test Case: Reverse Mapping");
    bypass = 0;
    for (i = 0; i < NUM_LANES; i++) begin
        swizzle_map[i] = NUM_LANES - 1 - i;
        input_lanes[i] = i + 20;
    end
    flatten_swizzle_map();
    flatten_input();
    @(posedge clk);
    @(posedge clk);
    unpack_output();
    for (i = 0; i < NUM_LANES; i++) begin
        expected_lanes[i] = input_lanes[NUM_LANES - 1 - i];
    end
    check_output("Reverse");
endtask

task test_custom;
    $display("Test Case: Custom Mapping");
    bypass = 0;
    swizzle_map[0] = 2;
    swizzle_map[1] = 0;
    swizzle_map[2] = 3;
    swizzle_map[3] = 1;
    input_lanes[0] = 8'hAA;
    input_lanes[1] = 8'hBB;
    input_lanes[2] = 8'hCC;
    input_lanes[3] = 8'hDD;
    flatten_swizzle_map();
    flatten_input();
    @(posedge clk);
    @(posedge clk);
    unpack_output();
    expected_lanes[0] = input_lanes[2];
    expected_lanes[1] = input_lanes[0];
    expected_lanes[2] = input_lanes[3];
    expected_lanes[3] = input_lanes[1];
    check_output("Custom");
endtask

task flatten_input;
    for (i = 0; i < NUM_LANES; i++) begin
        data_in[(i+1)*DATA_WIDTH-1 -: DATA_WIDTH] = input_lanes[i];
    end
endtask

task flatten_swizzle_map;
    for (i = 0; i < NUM_LANES; i++) begin
        swizzle_map_flat[(i+1)*$clog2(NUM_LANES)-1 -: $clog2(NUM_LANES)] = swizzle_map[i];
    end
endtask

task unpack_output;
    for (i = 0; i < NUM_LANES; i++) begin
        output_lanes[i] = data_out[(i+1)*DATA_WIDTH-1 -: DATA_WIDTH];
    end
endtask

task check_output(input string test_name);
    for (i = 0; i < NUM_LANES; i++) begin
        if (output_lanes[i] !== expected_lanes[i]) begin
            $display("[%s] ERROR: Lane %0d: Expected %h, Got %h", test_name, i, expected_lanes[i], output_lanes[i]);
        end else begin
            $display("[%s] PASS: Lane %0d = %h", test_name, i, output_lanes[i]);
        end
    end
    if (ENABLE_PARITY_CHECK) begin
        if (parity_error) begin
            $display("[%s] PARITY ERROR DETECTED", test_name);
        end else begin
            $display("[%s] Parity check passed", test_name);
        end
    end
endtask

endmodule

context.rtl/swizzler.sv:
`timescale 1ns/1ps

module swizzler #(
  parameter integer NUM_LANES           = 4,
  parameter integer DATA_WIDTH          = 8,
  parameter integer REGISTER_OUTPUT     = 0,
  parameter integer ENABLE_PARITY_CHECK = 0,
  parameter integer OP_MODE_WIDTH       = 2,
  parameter integer SWIZZLE_MAP_WIDTH   = $clog2(NUM_LANES)+1
)(
  input  wire                           clk,
  input  wire                           rst_n,
  input  wire                           bypass,
  input  wire [NUM_LANES*DATA_WIDTH-1:0]  data_in,
  input  wire [NUM_LANES*SWIZZLE_MAP_WIDTH-1:0] swizzle_map_flat,
  input  wire [OP_MODE_WIDTH-1:0]         operation_mode,
  output reg  [NUM_LANES*DATA_WIDTH-1:0]  data_out,
  output reg                            parity_error,
  output reg                            invalid_mapping_error
);

  // Unpack data_in into lanes
  wire [DATA_WIDTH-1:0] lane_in [0:NUM_LANES-1];
  genvar gi;
  generate
    for (gi = 0; gi < NUM_LANES; gi = gi + 1) begin : UNPACK_INPUT
      assign lane_in[gi] = data_in[DATA_WIDTH*(gi+1)-1 : DATA_WIDTH*gi];
    end
  endgenerate

  // Unpack swizzle_map_flat into swizzle_map array
  wire [SWIZZLE_MAP_WIDTH-1:0] swizzle_map [0:NUM_LANES-1];
  generate
    for (gi = 0; gi < NUM_LANES; gi = gi + 1) begin : UNPACK_SWIZZLE
      assign swizzle_map[gi] = swizzle_map_flat[SWIZZLE_MAP_WIDTH*(gi+1)-1 : SWIZZLE_MAP_WIDTH*gi];
    end
  endgenerate

  // Invalid mapping detection
  wire [NUM_LANES-1:0] invalid_map_flag;
  generate
    for (gi = 0; gi < NUM_LANES; gi = gi + 1) begin : INVALID_CHECK
      assign invalid_map_flag[gi] = (swizzle_map[gi] >= NUM_LANES) ? 1'b1 : 1'b0;
    end
  endgenerate
  wire invalid_mapping_detected = |invalid_map_flag;

  // Remap lanes according to swizzle_map or bypass
  wire [DATA_WIDTH-1:0] swizzled [0:NUM_LANES-1];
  generate
    for (gi = 0; gi < NUM_LANES; gi = gi + 1) begin : REMAP
      // Use lower bits of swizzle_map to index valid lanes.
      assign swizzled[gi] = bypass ? lane_in[gi] : lane_in[ swizzle_map[gi][$clog2(NUM_LANES)-1:0] ];
    end
  endgenerate

  // Pipeline Stage 1: Capture swizzled lanes
  reg [DATA_WIDTH-1:0] swizzle_reg [0:NUM_LANES-1];
  integer i;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      for (i = 0; i < NUM_LANES; i = i + 1)
        swizzle_reg[i] <= {DATA_WIDTH{1'b0}};
    else
      for (i = 0; i < NUM_LANES; i = i + 1)
        swizzle_reg[i] <= swizzled[i];
  end

  // Pipeline Stage 2: Capture operation mode and invalid mapping status
  reg [OP_MODE_WIDTH-1:0] op_reg;
  reg op_invalid_reg;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      op_reg <= {OP_MODE_WIDTH{1'b0}};
      op_invalid_reg <= 1'b0;
    end else begin
      op_reg <= operation_mode;
      op_invalid_reg <= invalid_mapping_detected;
    end
  end

  // Bit reversal function
  function automatic [DATA_WIDTH-1:0] bit_reverse;
    input [DATA_WIDTH-1:0] in;
    integer k;
    begin
      bit_reverse = {DATA_WIDTH{1'b0}};
      for (k = 0; k < DATA_WIDTH; k = k + 1)
        bit_reverse[k] = in[DATA_WIDTH-1-k];
    end
  endfunction

  // Pipeline Stage 3: Final output stage with bit reversal
  reg [DATA_WIDTH-1:0] final_reg [0:NUM_LANES-1];
  integer m;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      for (m = 0; m < NUM_LANES; m = m + 1)
        final_reg[m] <= {DATA_WIDTH{1'b0}};
    else
      for (m = 0; m < NUM_LANES; m = m + 1)
        final_reg[m] <= bit_reverse(swizzle_reg[m]);
  end

  // Pack final_reg into a flat output vector
  wire [NUM_LANES*DATA_WIDTH-1:0] final_packed;
  genvar q;
  generate
    for (q = 0; q < NUM_LANES; q = q + 1) begin : PACK_FINAL
      assign final_packed[DATA_WIDTH*(q+1)-1 : DATA_WIDTH*q] = final_reg[q];
    end
  endgenerate

  generate
    if (REGISTER_OUTPUT) begin : REG_FINAL
      always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
          data_out <= {NUM_LANES*DATA_WIDTH{1'b0}};
        else
          data_out <= final_packed;
      end
    end else begin : COMB_FINAL
      always @* begin
        data_out = final_packed;
      end
    end
  endgenerate

  // Updated parity error calculation using a generate block
  generate
    if (ENABLE_PARITY_CHECK) begin : GEN_PARITY
      // Calculate parity from final_reg if parity check is enabled.
      wire [NUM_LANES-1:0] final_parity;
      genvar p;
      for (p = 0; p < NUM_LANES; p = p + 1) begin : PARITY_CALC
        assign final_parity[p] = ^final_reg[p];
      end
      wire computed_parity = |final_parity;
      always @* begin
        parity_error = computed_parity;
      end
    end else begin : NO_PARITY
      // Drive parity_error to 0 when parity check is disabled.
      always @* begin
        parity_error = 1'b0;
      end
    end
  endgenerate

  // Pass the invalid mapping flag
  always @* begin
    invalid_mapping_error = op_invalid_reg;
  end

endmodule

context.verif/swizzler_tb.sv:
`timescale 1ns/1ps

module tb_swizzler;
  parameter NUM_LANES = 4;
  parameter DATA_WIDTH = 8;
  parameter REGISTER_OUTPUT = 1;
  parameter ENABLE_PARITY_CHECK = 0;
  parameter OP_MODE_WIDTH = 2;
  parameter SWIZZLE_MAP_WIDTH = 3;

  reg clk;
  reg rst_n;
  reg bypass;
  reg [NUM_LANES*DATA_WIDTH-1:0] data_in;
  reg [NUM_LANES*SWIZZLE_MAP_WIDTH-1:0] swizzle_map_flat;
  reg [OP_MODE_WIDTH-1:0] operation_mode;
  wire [NUM_LANES*DATA_WIDTH-1:0] data_out;
  wire parity_error;
  wire invalid_mapping_error;

  swizzler #(
    .NUM_LANES(NUM_LANES),
    .DATA_WIDTH(DATA_WIDTH),
    .REGISTER_OUTPUT(REGISTER_OUTPUT),
    .ENABLE_PARITY_CHECK(ENABLE_PARITY_CHECK),
    .OP_MODE_WIDTH(OP_MODE_WIDTH),
    .SWIZZLE_MAP_WIDTH(SWIZZLE_MAP_WIDTH)
  ) dut (
    .clk(clk),
    .rst_n(rst_n),
    .bypass(bypass),
    .data_in(data_in),
    .swizzle_map_flat(swizzle_map_flat),
    .operation_mode(operation_mode),
    .data_out(data_out),
    .parity_error(parity_error),
    .invalid_mapping_error(invalid_mapping_error)
  );

  reg [DATA_WIDTH-1:0] expected [0:NUM_LANES-1];
  reg [DATA_WIDTH-1:0] out_lane [0:NUM_LANES-1];
  integer i;

  function [DATA_WIDTH-1:0] bit_reverse;
    input [DATA_WIDTH-1:0] in;
    integer j;
    reg [DATA_WIDTH-1:0] out;
    begin
      out = 0;
      for(j = 0; j < DATA_WIDTH; j = j + 1)
        out[j] = in[DATA_WIDTH-1-j];
      bit_reverse = out;
    end
  endfunction

  function [DATA_WIDTH-1:0] get_lane;
    input integer index;
    begin
      get_lane = data_out[DATA_WIDTH*(index+1)-1 -: DATA_WIDTH];
    end
  endfunction

  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  initial begin
    rst_n = 0;
    bypass = 0;
    data_in = 0;
    swizzle_map_flat = 0;
    operation_mode = 0;
    #12;
    rst_n = 1;
    repeat (5) @(posedge clk);
    // TEST 1: Bypass disabled, identity mapping with bit reversal.
    data_in = {8'h04, 8'h03, 8'h02, 8'h01};
    swizzle_map_flat = {3'b011, 3'b010, 3'b001, 3'b000};
    bypass = 0;
    operation_mode = 0;
    repeat (5) @(posedge clk);
    for(i = 0; i < NUM_LANES; i = i + 1)
      out_lane[i] = get_lane(i);
    expected[0] = bit_reverse(8'h01);
    expected[1] = bit_reverse(8'h02);
    expected[2] = bit_reverse(8'h03);
    expected[3] = bit_reverse(8'h04);
    if(out_lane[0]==expected[0] && out_lane[1]==expected[1] &&
       out_lane[2]==expected[2] && out_lane[3]==expected[3])
      $display("TEST 1 PASS");
    else
      $display("TEST 1 FAIL: Expected %h %h %h %h, Got %h %h %h %h",
               expected[0], expected[1], expected[2], expected[3],
               out_lane[0], out_lane[1], out_lane[2], out_lane[3]);
    if(invalid_mapping_error==0)
      $display("TEST 1 INVALID MAPPING PASS");
    else
      $display("TEST 1 INVALID MAPPING FAIL");

    // TEST 2: Reverse mapping.
    data_in = {8'hAA, 8'hBB, 8'hCC, 8'hDD};
    swizzle_map_flat = {3'b000, 3'b001, 3'b010, 3'b011};
    bypass = 0;
    operation_mode = 0;
    repeat (5) @(posedge clk);
    for(i = 0; i < NUM_LANES; i = i + 1)
      out_lane[i] = get_lane(i);
    // Expected output is reversed compared to input lane order.
    expected[0] = bit_reverse(8'hAA);
    expected[1] = bit_reverse(8'hBB);
    expected[2] = bit_reverse(8'hCC);
    expected[3] = bit_reverse(8'hDD);
    if(out_lane[0]==expected[0] && out_lane[1]==expected[1] &&
       out_lane[2]==expected[2] && out_lane[3]==expected[3])
      $display("TEST 2 PASS");
    else
      $display("TEST 2 FAIL: Expected %h %h %h %h, Got %h %h %h %h",
               expected[0], expected[1], expected[2], expected[3],
               out_lane[0], out_lane[1], out_lane[2], out_lane[3]);

    // TEST 3: Bypass mode active.
    data_in = {8'h11, 8'h22, 8'h33, 8'h44};
    swizzle_map_flat = {3'b001, 3'b000, 3'b011, 3'b010};
    bypass = 1;
    operation_mode = 0;
    repeat (5) @(posedge clk);
    for(i = 0; i < NUM_LANES; i = i + 1)
      out_lane[i] = get_lane(i);
    expected[0] = bit_reverse(8'h44);
    expected[1] = bit_reverse(8'h33);
    expected[2] = bit_reverse(8'h22);
    expected[3] = bit_reverse(8'h11);
    if(out_lane[0]==expected[0] && out_lane[1]==expected[1] &&
       out_lane[2]==expected[2] && out_lane[3]==expected[3])
      $display("TEST 3 PASS");
    else
      $display("TEST 3 FAIL: Expected %h %h %h %h, Got %h %h %h %h",
               expected[0], expected[1], expected[2], expected[3],
               out_lane[0], out_lane[1], out_lane[2], out_lane[3]);

    // TEST 4: Invalid mapping detection.
    data_in = {8'h55, 8'h66, 8'h77, 8'h88};
    swizzle_map_flat = {3'b011, 3'b010, 3'b001, 3'b100};
    bypass = 0;
    operation_mode = 0;
    repeat (5) @(posedge clk);
    if(invalid_mapping_error==1)
      $display("TEST 4 PASS: Invalid mapping detected");
    else
      $display("TEST 4 FAIL: Invalid mapping not detected");
    $finish;
  end

endmodule

context.rtl/weight_stationary_pe.sv:
`timescale 1ns/1ns

//-----------------------------
// Processing Element
//-----------------------------
module weight_stationary_pe #(
  parameter DATA_WIDTH = 8  // Bit width of weights and activations
)
(
  input  wire                 clk,
  input  wire                 reset,
  input  wire                 load_weight,   // load the weight into the PE if high
  input  wire                 valid,         // signal to indicate new data is valid

  input  wire [DATA_WIDTH-1:0] input_in,     // input from left PE or from memory
  input  wire [DATA_WIDTH-1:0] weight,       // new weight to be loaded
  input  wire [DATA_WIDTH-1:0] psum_in,      // accumulated sum from the PE above

  output reg  [DATA_WIDTH-1:0] input_out,    // pass input to the right PE
  output reg  [DATA_WIDTH-1:0] psum_out      // pass accumulated sum downward
);

  reg [DATA_WIDTH-1:0] weight_reg; // register for holding weight locally

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      weight_reg <= {DATA_WIDTH{1'b0}};
      input_out  <= {DATA_WIDTH{1'b0}};
      psum_out   <= {DATA_WIDTH{1'b0}};
    end 
    else begin
      // Load the new weight if load_weight is high
      if (load_weight) begin
        weight_reg <= weight;
      end

      // Only update psum_out and input_out if 'valid' is high
      if (valid) begin
        psum_out  <= psum_in + (input_in * weight_reg);
        input_out <= input_in;
      end
      else begin
        // Hold the old values when not valid
        psum_out  <= psum_out;
        input_out <= input_out;
      end
    end
  end

endmodule

context.verif/systolic_array_tb.sv:
`timescale 1ns/1ns

module systolic_array_tb;

  // --------------------------------------------------------------------------
  // Parameters & Local Variables
  // --------------------------------------------------------------------------
  localparam DATA_WIDTH = 8;
  localparam CLK_PERIOD = 10;  // 10 ns = 100 MHz

  // We'll run multiple tests in sequence.
  // For each test, we store:
  //    w00, w01, w10, w11, x0, x1, and the expected y0, y1
  // The results are: 
  //    y0 = (x0 * w00) + (x1 * w10)
  //    y1 = (x0 * w01) + (x1 * w11)
  //
  // NOTE: In the provided design, psum_out is only 8 bits, so the results
  //       may wrap around (overflow) if the sum exceeds 8 bits (255 for unsigned).
  //       If you want to test overflow behavior, see the last test case.

  // We'll store multiple test vectors in arrays.
  // Increase TEST_COUNT if you add more test vectors.
  localparam TEST_COUNT = 7;

  reg [DATA_WIDTH-1:0] w00_test [0:TEST_COUNT-1];
  reg [DATA_WIDTH-1:0] w01_test [0:TEST_COUNT-1];
  reg [DATA_WIDTH-1:0] w10_test [0:TEST_COUNT-1];
  reg [DATA_WIDTH-1:0] w11_test [0:TEST_COUNT-1];
  reg [DATA_WIDTH-1:0] x0_test  [0:TEST_COUNT-1];
  reg [DATA_WIDTH-1:0] x1_test  [0:TEST_COUNT-1];
  reg [DATA_WIDTH-1:0] y0_exp   [0:TEST_COUNT-1];
  reg [DATA_WIDTH-1:0] y1_exp   [0:TEST_COUNT-1];

  // --------------------------------------------------------------------------
  // Testbench signals
  // --------------------------------------------------------------------------
  reg                      clk;
  reg                      reset;
  reg                      load_weights;
  reg                      start;
  reg  [DATA_WIDTH-1:0]    w00, w01, w10, w11;
  reg  [DATA_WIDTH-1:0]    x0,  x1;
  wire [DATA_WIDTH-1:0]    y0,  y1;
  wire                     done;

  // --------------------------------------------------------------------------
  // Instantiate the DUT (Device Under Test)
  // --------------------------------------------------------------------------
  systolic_array #(
    .DATA_WIDTH(DATA_WIDTH)
  ) dut (
    .clk         (clk),
    .reset       (reset),
    .load_weights(load_weights),
    .start       (start),
    .w00         (w00),
    .w01         (w01),
    .w10         (w10),
    .w11         (w11),
    .x0          (x0),
    .x1          (x1),
    .y0          (y0),
    .y1          (y1),
    .done        (done)
  );

  // --------------------------------------------------------------------------
  // Clock Generation
  // --------------------------------------------------------------------------
  always begin
    clk = 1'b0; 
    #(CLK_PERIOD/2);
    clk = 1'b1; 
    #(CLK_PERIOD/2);
  end

  // --------------------------------------------------------------------------
  // Test Vector Initialization
  // --------------------------------------------------------------------------
  initial begin
    // Test 0: Simple: All weights = 1, x0=2, x1=3
    //   y0 = 2*1 + 3*1 = 5
    //   y1 = 2*1 + 3*1 = 5
    w00_test[0] = 8'd1; w01_test[0] = 8'd1; w10_test[0] = 8'd1; w11_test[0] = 8'd1;
    x0_test[0]  = 8'd2; x1_test[0]  = 8'd3;
    y0_exp[0]   = 8'd5; y1_exp[0]   = 8'd5;

    // Test 1: Another normal case
    //   w00=2, w01=3, w10=4, w11=5, x0=6, x1=7
    //   y0 = 6*2 + 7*4 = 12 + 28 = 40 (0x28)
    //   y1 = 6*3 + 7*5 = 18 + 35 = 53 (0x35)
    w00_test[1] = 8'd2;  w01_test[1] = 8'd3;  w10_test[1] = 8'd4;  w11_test[1] = 8'd5;
    x0_test[1]  = 8'd6;  x1_test[1]  = 8'd7;
    y0_exp[1]   = 8'd40; y1_exp[1]   = 8'd53;

    // Test 2: Check zero weights
    //   w00=0, w01=0, w10=0, w11=0, x0=10, x1=20
    //   y0 = 10*0 + 20*0 = 0
    //   y1 = 10*0 + 20*0 = 0
    w00_test[2] = 8'd0;  w01_test[2] = 8'd0;  w10_test[2] = 8'd0;  w11_test[2] = 8'd0;
    x0_test[2]  = 8'd10; x1_test[2]  = 8'd20;
    y0_exp[2]   = 8'd0;  y1_exp[2]   = 8'd0;

    // Test 3: Check zero inputs
    //   w00=5, w01=4, w10=3, w11=2, x0=0, x1=0
    //   y0 = 0*5 + 0*3 = 0
    //   y1 = 0*4 + 0*2 = 0
    w00_test[3] = 8'd5;  w01_test[3] = 8'd4;  w10_test[3] = 8'd3;  w11_test[3] = 8'd2;
    x0_test[3]  = 8'd0;  x1_test[3]  = 8'd0;
    y0_exp[3]   = 8'd0;  y1_exp[3]   = 8'd0;

    // Test 4: Check maximum values (unsigned interpretation)
    //   w00=255, w01=255, w10=255, w11=255, x0=255, x1=255
    //   The multiplication 255*255 = 65025 decimal = 0xFE01 in 16 bits,
    //   but only lower 8 bits stored => 0x01. Then psum_in + 0x01 => might cause repeated overflow.
    //   Pipeline flow for y0 =>  (255*255)(LSB only) + (255*255)(LSB only) ...
    //   This test will show how it saturates/overflows within 8 bits.
    //   Expected result is not typical for "true multiply," it's the truncated 8-bit result:
    //   The design does: psum_out <= (psum_in + (input_in * weight_reg)) & 0xFF
    //   So 255*255=65025 => 8-bit truncated = 0x01
    //   So y0 = 0x01 + 0x01 = 0x02, y1 = 0x01 + 0x01 = 0x02 in final pipeline stage
    //   (Because of the pipeline, the final sums can shift. Let's keep it simple 
    //    and say we expect 2 for both. For a pure 2×2 multiply, "real" result is 255*255*2=~130050, 
    //    but we are only capturing LSB in each step.)
    w00_test[4] = 8'hFF; w01_test[4] = 8'hFF; w10_test[4] = 8'hFF; w11_test[4] = 8'hFF;
    x0_test[4]  = 8'hFF; x1_test[4]  = 8'hFF;
    y0_exp[4]   = 8'd2;  y1_exp[4]   = 8'd2;

    // Test 5: Mixed smaller large values for partial demonstration
    //   w00=100, w01=150, w10=200, w11=250, x0=8, x1=3
    //   y0 = 8*100 + 3*200 = 800 + 600 = 1400 => truncated to 8 bits => 1400 mod 256 = 1400 - 5*256= 1400-1280=120
    //   y1 = 8*150 + 3*250 = 1200 + 750 = 1950 => mod 256 => 1950 - 7*256= 1950-1792=158
    w00_test[5] = 8'd100; w01_test[5] = 8'd150; w10_test[5] = 8'd200; w11_test[5] = 8'd250;
    x0_test[5]  = 8'd8;   x1_test[5]  = 8'd3;
    y0_exp[5]   = 8'd120; y1_exp[5]   = 8'd158;

    // Test 6: Minimal/edge case (all zeros) repeated, to show no glitch
    //   wXX=0, xX=0 => y0=0, y1=0
    w00_test[6] = 8'd0;  w01_test[6] = 8'd0;  w10_test[6] = 8'd0;  w11_test[6] = 8'd0;
    x0_test[6]  = 8'd0;  x1_test[6]  = 8'd0;
    y0_exp[6]   = 8'd0;  y1_exp[6]   = 8'd0;
  end

  // --------------------------------------------------------------------------
  // Main Test Sequence
  // --------------------------------------------------------------------------
  integer i;
  initial begin
    // Display header
    $display("==========================================");
    $display(" Starting 2x2 Systolic Array Testbench...");
    $display("==========================================");

    // Initialize signals
    clk           = 1'b0;
    reset         = 1'b1;
    load_weights  = 1'b0;
    start         = 1'b0;
    w00           = {DATA_WIDTH{1'b0}};
    w01           = {DATA_WIDTH{1'b0}};
    w10           = {DATA_WIDTH{1'b0}};
    w11           = {DATA_WIDTH{1'b0}};
    x0            = {DATA_WIDTH{1'b0}};
    x1            = {DATA_WIDTH{1'b0}};

    // Wait a few cycles before deasserting reset
    #(5*CLK_PERIOD);
    reset = 1'b0;
    #(2*CLK_PERIOD);

    // Run through each test
    for (i = 0; i < TEST_COUNT; i = i + 1) begin
      // 1) Load the weights
      w00 = w00_test[i];
      w01 = w01_test[i];
      w10 = w10_test[i];
      w11 = w11_test[i];

      // Assert load_weights for at least one cycle so the PEs can latch the new weights
      load_weights = 1'b1;
      #(CLK_PERIOD);
      load_weights = 1'b0;

      // 2) Apply inputs and start
      x0    = x0_test[i];
      x1    = x1_test[i];
      start = 1'b1;

      // Wait for done to assert
      wait(done === 1'b1);

      // Once done is high for at least one cycle, we can capture the outputs.
      //   (You could wait for the negedge of done as well if the design pulses it, 
      //    but in this example, once it goes high it remains high until start is deasserted)
      #(CLK_PERIOD);

      // 3) Compare with expected
      if ((y0 === y0_exp[i]) && (y1 === y1_exp[i])) begin
        $display("Test %0d PASSED. y0=%0d, y1=%0d (Expected %0d, %0d)",
                  i, y0, y1, y0_exp[i], y1_exp[i]);
      end else begin
        $display("Test %0d FAILED. y0=%0d, y1=%0d (Expected %0d, %0d)",
                  i, y0, y1, y0_exp[i], y1_exp[i]);
      end

      // Deassert start and wait a couple of cycles before next test
      start = 1'b0;
      #(2*CLK_PERIOD);
    end

    // End of all tests
    $display("==========================================");
    $display(" All tests completed.");
    $display("==========================================");

    $finish;
  end

endmodule
